package kindergarten

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

// Garden maps each child's name to the four plants they are responsible for.
type Garden struct {
	plants map[string][]string
}

// plantNames maps the diagram codes to the plant names.
var plantNames = map[byte]string{
	'G': "grass",
	'C': "clover",
	'R': "radishes",
	'V': "violets",
}

var errInvalidDiagram = errors.New("invalid diagram")

// NewGarden creates a Garden from a two-row diagram and a list of children.
//
// The diagram argument starts each row with a '\n'.  This allows Go's
// raw string literals to present diagrams in source code nicely as two
// rows flush left, for example,
//
//	diagram := `
//	VVCCGG
//	VVCCGG`
//
// The children are assigned to pairs of cups in alphabetical order,
// so the first child in the sorted list gets the two leftmost cups of
// each row, and so on. The children argument is not modified.
func NewGarden(diagram string, children []string) (*Garden, error) {
	rows := strings.Split(diagram, "\n")
	if len(rows) != 3 || rows[0] != "" || len(rows[1]) != len(rows[2]) {
		return nil, errInvalidDiagram
	}
	if len(rows[1])%2 != 0 {
		return nil, fmt.Errorf("%w: number of cups must be even", errInvalidDiagram)
	}
	for _, row := range rows[1:] {
		for i := 0; i < len(row); i++ {
			if _, ok := plantNames[row[i]]; !ok {
				return nil, fmt.Errorf("%w: unknown cup code %q", errInvalidDiagram, row[i])
			}
		}
	}

	sorted := make([]string, len(children))
	copy(sorted, children)
	sort.Strings(sorted)
	for i := 1; i < len(sorted); i++ {
		if sorted[i] == sorted[i-1] {
			return nil, fmt.Errorf("duplicate name %q", sorted[i])
		}
	}

	g := &Garden{plants: make(map[string][]string, len(sorted))}
	for i, name := range sorted {
		if 2*i+1 >= len(rows[1]) {
			break // not enough cups for the remaining children
		}
		g.plants[name] = []string{
			plantNames[rows[1][2*i]],
			plantNames[rows[1][2*i+1]],
			plantNames[rows[2][2*i]],
			plantNames[rows[2][2*i+1]],
		}
	}
	return g, nil
}

// Plants returns the four plants assigned to the named child. The
// returned bool is false if the child is not in the garden.
func (g *Garden) Plants(child string) ([]string, bool) {
	plants, ok := g.plants[child]
	return plants, ok
}
